// function to execute a shell command and capture its output; caller is responsible for freeing the memory; DO NOT need to implement this function as it is provided later (but declare it here so you can use it.
std::string execute_command(const std::string& command);

/**
Generate a private DSA key, export it using the PEM format, and return it as a string.
Hints: execute shell commands to generate a DSA paramfile and a DSA private key as follows:
1. `openssl dsaparam -out <a temporary file to store params> <key_length>`
2. `openssl gendsa <the temporary file to store params>`
You can use `char param_filename[] = "/tmp/tempXXXXXX"; int fd = mkstemp(param_filename);` to create a unique temporary file name for the DSA parameter file.

@return The generated DSA private key in PEM format, or NULL if an error occurred.
*/
std::string create_dsa_key() {
    // Create a unique temporary file name for DSA parameters
    // mkstemp modifies the template string to include a unique suffix.
    char param_filename_template[] = "/tmp/temp_dsa_params_XXXXXX";
    int fd = mkstemp(param_filename_template);

    if (fd == -1) {
        // Error creating temporary file template.
        // mkstemp failed, likely due to permissions or invalid template.
        // Return empty string to indicate error, as NULL is not applicable for std::string.
        return "";
    }
    // Close the file descriptor immediately. openssl will create/overwrite the file by name.
    // It's crucial to close it so openssl can open and write to it.
    close(fd);
    std::string param_file_str = param_filename_template;

    std::string private_key_pem; // Declare here to ensure scope for cleanup and return

    // 1. Generate DSA parameters and store them in the temporary file
    const int key_length = 2048; // A common and secure key length for DSA
    std::string dsaparam_command = "openssl dsaparam -out " + param_file_str + " " + std::to_string(key_length);
    std::string dsaparam_output = execute_command(dsaparam_command);

    // openssl dsaparam typically prints nothing to stdout on success.
    // If it prints something, it's likely an error message.
    if (!dsaparam_output.empty()) {
        // Error occurred during dsaparam generation
        unlink(param_filename_template); // Clean up the temporary file
        return ""; // Return empty string to indicate error
    }

    // 2. Generate the DSA private key using the parameters
    // openssl gendsa reads parameters from the file and outputs the private key to stdout.
    std::string gendsa_command = "openssl gendsa -in " + param_file_str;
    private_key_pem = execute_command(gendsa_command);

    // Clean up the temporary parameter file regardless of success or failure
    // This ensures the file is removed even if gendsa fails or the key is invalid.
    unlink(param_filename_template);

    // Check if the key generation was successful and the output is a valid PEM key.
    // A valid DSA private key in PEM format must start with "-----BEGIN DSA PRIVATE KEY-----".
    // This is a more robust check than just checking for emptiness, as openssl might
    // print an error message to stdout on failure, which would not be empty,
    // but would also not be a valid key.
    if (private_key_pem.empty() || private_key_pem.find("-----BEGIN DSA PRIVATE KEY-----") == std::string::npos) {
        return ""; // Return empty string to indicate error
    }

    return private_key_pem;
}
